import{_ as e,o as _,c as t,a3 as s}from"./chunks/framework.DdpBa4_E.js";const o="/ReadBooks/assets/image-005.DM5DSLg-.jpg",h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/55-“尊重个性的家庭”也是下流阶层居多.md","filePath":"books/xialiu-shehui/55-“尊重个性的家庭”也是下流阶层居多.md","lastUpdated":1794732511000}'),p={name:"books/xialiu-shehui/55-“尊重个性的家庭”也是下流阶层居多.md"};function i(r,a,l,n,d,c){return _(),t("div",null,[...a[0]||(a[0]=[s('<h2 id="尊重个性的家庭-也是下流阶层居多" tabindex="-1">“尊重个性的家庭”也是下流阶层居多 <a class="header-anchor" href="#尊重个性的家庭-也是下流阶层居多" aria-label="Permalink to &quot;“尊重个性的家庭”也是下流阶层居多&quot;">​</a></h2><p>颇为耐人寻味的是，在回答何为理想的家庭的时候，选择“尊重个性的家庭”“各自独立的家庭”的人数，在团块世代中不论男女，都是上流阶层中所占比例较高（见表5-4）。</p><p>表5-4　不同阶层意识人群选择“尊重个性”为理想家庭者的比例</p><p><img src="'+o+'" alt="" loading="lazy"></p><p>资料出处：Culture Studies研究所、e-FALCON共同实施的“欲求调查”</p><p>然而，在团块次代当中，认为这样的家庭才是理想家庭的人却是“下流”者居多。看来，所谓像朋友一般的亲子关系，已经作为一种生活样式，从团块世代的上流阶层蔓延到团块次代的下流阶层了。</p><p>的确，所谓“有个性”或“我行我素”这样的说法，是在团块世代的青年期开始出现的，此后逐渐扩大到整个社会。例如，1967年开始销售的面向团块世代男性的资生堂化妆品“MG5”，将男性的个性表现作为广告的诉求重点，1970年左右日产汽车公司“蓝鸟”轿车的广告语则是“优秀的个性集团”。除此之外，在笔者的印象当中，上世纪70年代的广告里经常使用像“个性”这样的词汇。</p><p>总之，作为消费社会主力军的团块世代，在上世纪60年代以后可以说是把“有个性”当成了一件好事，特别是那些左右社会舆论的阶层，几乎把追求个性的志向当成咒语一般拼命念个不停。</p><p>在过去三十年中，日本社会逐渐发展成为以团块世代为中心的社会，重视个性与自我主张的思想也随之渐渐蔓延，社会也更加富庶了，在此过程中，日本社会终于成为这样一个社会：即使是下流阶层的年轻人，也开始拼命注重起个性和所谓的“自我主张”来。</p>',9)])])}const m=e(p,[["render",i]]);export{h as __pageData,m as default};
